const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let options={},rows=null,error='',loading=false,generation=0,student='',skill='',allAttempts=false;
export function initBookGrades(callbacks){options=callbacks;document.querySelector('#app').addEventListener('change',event=>{const filter=event.target.dataset.bookGradeFilter;if(!filter)return;if(filter==='student')student=event.target.value;if(filter==='skill')skill=event.target.value;if(filter==='attempts')allAttempts=event.target.value==='all';options.render?.();});document.querySelector('#app').addEventListener('click',event=>{const action=event.target.closest('[data-book-grade-action]')?.dataset.bookGradeAction;if(action==='refresh')void load(true);if(action==='export')exportRows();});}
export function resetBookGrades(){generation++;rows=null;error='';loading=false;student='';skill='';}
async function load(force=false){if(loading||!force&&rows)return;const version=generation;loading=true;error='';try{const result=await options.request('/api/teacher/book-grades');if(version===generation)rows=result.submissions;}catch(e){if(version===generation)error=e.message;}finally{if(version===generation){loading=false;options.render?.();}}}
function visibleRows(){const seen=new Set();return (rows||[]).filter(row=>{if(student&&row.student_id!==student||skill&&row.kind!==skill)return false;const key=row.student_id+':'+row.book_id+':'+row.book_activity_id;if(!allAttempts&&seen.has(key))return false;seen.add(key);return true;});}
export function bookGradesHTML(){void load();const visible=visibleRows(),students=[...new Map((rows||[]).map(row=>[row.student_id,row.student_name])).entries()];return `<section class="card book-grades"><div class="section-head"><div><h2>Student-book grading sheets</h2><p>Book activities are recorded here when students submit. Auto-marked answers use a verified key; other responses wait for your review.</p></div><div class="button-row"><button class="button secondary" data-book-grade-action="refresh">${loading?'Loading…':'Refresh grades'}</button><button class="button soft" data-book-grade-action="export" ${!visible.length?'disabled':''}>Download CSV</button></div></div>${error?`<p class="notice warm" role="alert">${esc(error)}</p>`:''}<div class="book-grades-controls"><label>Student<select data-book-grade-filter="student"><option value="">All students</option>${students.map(([id,name])=>`<option value="${esc(id)}" ${student===id?'selected':''}>${esc(name)}</option>`).join('')}</select></label><label>Course<select data-book-grade-filter="skill"><option value="">All courses</option><option value="reading" ${skill==='reading'?'selected':''}>Reading</option><option value="listening" ${skill==='listening'?'selected':''}>Listening</option></select></label><label>Attempts<select data-book-grade-filter="attempts"><option value="latest" ${!allAttempts?'selected':''}>Latest per activity</option><option value="all" ${allAttempts?'selected':''}>All attempts</option></select></label></div>${visible.length?`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Book activity</th><th>Answered</th><th>Auto marks</th><th>Teacher mark</th><th>Status</th><th></th></tr></thead><tbody>${visible.map(row=>`<tr><td><strong>${esc(row.student_name)}</strong></td><td>${esc(row.title)}<small>${new Date(row.created_at).toLocaleString()}</small></td><td>${row.answered_count} / ${row.question_count}</td><td>${row.total?row.score+' / '+row.total:'—'}${row.pending_count?`<small>${row.pending_count} for teacher review</small>`:''}</td><td>${esc(row.reviewed&&row.teacher_score||'—')}</td><td><span class="pill">${row.reviewed?'Reviewed':row.pending_count?'Teacher review':'Auto-marked'}</span></td><td><button class="button secondary" data-cloud-action="open-work" data-id="${esc(row.id)}">Open answers</button></td></tr>`).join('')}</tbody></table></div>`:`<p class="small muted">${loading?'Opening your grading sheets…':'No submitted book activities match these filters yet.'}</p>`}</section>`;}
function exportRows(){const cell=value=>{let s=String(value??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const header=['Student','Course','Activity','Answered','Question count','Auto score','Auto total','For teacher review','Teacher mark','Reviewed','Submitted'];const values=visibleRows().map(row=>[row.student_name,row.kind,row.title,row.answered_count,row.question_count,row.score,row.total,row.pending_count,row.teacher_score,row.reviewed?'Yes':'No',row.created_at]);const blob=new Blob(['\ufeff'+[header,...values].map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Richmount_Student_Book_Grades.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
